// Copies the JSON schemas this service validates against from /contracts into
// src/contracts/generated. The output is committed because the Docker build context
// (backend/) does not contain /contracts.
//
//   npm run contracts:sync    rewrite the generated files
//   npm run contracts:check   exit 1 when a generated file differs from the contract
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import prettier from 'prettier';
import { parse } from 'yaml';

const SERVICE_ROOT = path.resolve(import.meta.dirname, '..');
const CONTRACT_FILE = 'contracts/openapi/golden-flow-api.yaml';
const CONTRACT_PATH = path.resolve(SERVICE_ROOT, '../..', CONTRACT_FILE);
const GENERATED_DIR = path.join(SERVICE_ROOT, 'src/contracts/generated');

interface GeneratedSchema {
  schemaName: string;
  exportName: string;
  fileName: string;
}

const SCHEMAS: GeneratedSchema[] = [
  {
    schemaName: 'OtpEmailRequest',
    exportName: 'otpEmailRequestSchema',
    fileName: 'otpEmailRequest.schema.ts',
  },
];

interface OpenApiDocument {
  components?: { schemas?: Record<string, unknown> };
}

async function render(document: OpenApiDocument, schema: GeneratedSchema): Promise<string> {
  const definition = document.components?.schemas?.[schema.schemaName];
  if (definition === undefined) {
    throw new Error(`${CONTRACT_FILE} has no components.schemas.${schema.schemaName}`);
  }
  const source = [
    `// Generated by scripts/sync-contracts.ts from ${CONTRACT_FILE}`,
    `// (#/components/schemas/${schema.schemaName}). Do not edit; run \`npm run contracts:sync\`.`,
    `export const ${schema.exportName} = ${JSON.stringify(definition)} as const;`,
    '',
  ].join('\n');
  const target = path.join(GENERATED_DIR, schema.fileName);
  const options = await prettier.resolveConfig(target);
  return prettier.format(source, { ...options, filepath: target, endOfLine: 'lf' });
}

// Compared without CR so a Windows checkout with core.autocrlf does not report drift.
function normalize(text: string): string {
  return text.replace(/\r\n/g, '\n');
}

async function main(): Promise<void> {
  const check = process.argv.includes('--check');
  const document = parse(await readFile(CONTRACT_PATH, 'utf8')) as OpenApiDocument;
  const stale: string[] = [];

  for (const schema of SCHEMAS) {
    const target = path.join(GENERATED_DIR, schema.fileName);
    const expected = await render(document, schema);
    if (check) {
      const actual = await readFile(target, 'utf8').catch(() => '');
      if (normalize(actual) !== expected) {
        stale.push(path.relative(SERVICE_ROOT, target));
      }
    } else {
      await writeFile(target, expected);
    }
  }

  if (stale.length > 0) {
    console.error(`Out of date with ${CONTRACT_FILE}: ${stale.join(', ')}`);
    console.error('Run `npm run contracts:sync` and commit the result.');
    process.exit(1);
  }
}

await main();
